window.EST = {"duration":263.45,"groups":[{"id":"title","n":1,"section":1,"title":true,"first":0.05,"end":3.35,"caps":[{"text":"What if Earth stopped spinning for 1 second?","show":0.05,"hide":3.35,"words":[{"text":"What","start":0.05},{"text":"if","start":0.339},{"text":"Earth","start":0.628},{"text":"stopped","start":0.916},{"text":"spinning","start":1.205},{"text":"for","start":1.494},{"text":"1","start":1.782},{"text":"second?","start":2.071}]}]},{"id":"start","n":2,"section":1,"title":false,"first":4.25,"end":8.1,"caps":[{"text":"5:42 PM, on the equator. The ground just stopped turning.","show":4.25,"hide":8.1,"words":[{"text":"5:42","start":4.25},{"text":"PM,","start":4.52},{"text":"on","start":4.789},{"text":"the","start":5.059},{"text":"equator.","start":5.328},{"text":"The","start":5.598},{"text":"ground","start":5.867},{"text":"just","start":6.137},{"text":"stopped","start":6.406},{"text":"turning.","start":6.676}]}]},{"id":"first","n":3,"section":1,"title":false,"first":8.8,"end":14.9,"caps":[{"text":"East of town, a hill stopped with it.","show":8.8,"hide":11.65,"words":[{"text":"East","start":8.8},{"text":"of","start":9.049},{"text":"town,","start":9.299},{"text":"a","start":9.548},{"text":"hill","start":9.798},{"text":"stopped","start":10.047},{"text":"with","start":10.296},{"text":"it.","start":10.546}]},{"text":"Nothing else did.","show":13.05,"hide":14.9,"words":[{"text":"Nothing","start":13.05},{"text":"else","start":13.482},{"text":"did.","start":13.913}]}]},{"id":"speed","n":4,"section":1,"title":false,"first":16.3,"end":25.85,"caps":[{"text":"This station always moves east at 1,670 km/h. You never feel it, because everything moves together.","show":16.3,"hide":20.5,"words":[{"text":"This","start":16.3},{"text":"station","start":16.484},{"text":"always","start":16.668},{"text":"moves","start":16.851},{"text":"east","start":17.035},{"text":"at","start":17.219},{"text":"1,670","start":17.403},{"text":"km/h.","start":17.586},{"text":"You","start":17.77},{"text":"never","start":17.954},{"text":"feel","start":18.138},{"text":"it,","start":18.321},{"text":"because","start":18.505},{"text":"everything","start":18.689},{"text":"moves","start":18.873},{"text":"together.","start":19.056}]},{"text":"And something just got in front of the Sun.","show":22.7,"hide":25.85,"words":[{"text":"And","start":22.7},{"text":"something","start":22.945},{"text":"just","start":23.19},{"text":"got","start":23.435},{"text":"in","start":23.68},{"text":"front","start":23.925},{"text":"of","start":24.17},{"text":"the","start":24.415},{"text":"Sun.","start":24.66}]}]},{"id":"bolts","n":5,"section":1,"title":false,"first":27.25,"end":42,"caps":[{"text":"The station was bolted to the ground. It didn't matter.","show":27.25,"hide":31,"words":[{"text":"The","start":27.25},{"text":"station","start":27.513},{"text":"was","start":27.775},{"text":"bolted","start":28.038},{"text":"to","start":28.3},{"text":"the","start":28.563},{"text":"ground.","start":28.825},{"text":"It","start":29.088},{"text":"didn't","start":29.35},{"text":"matter.","start":29.613}]},{"text":"To stop with the ground, its steel would have to be 50 times stronger than steel is.","show":32.2,"hide":36.4,"words":[{"text":"To","start":32.2},{"text":"stop","start":32.373},{"text":"with","start":32.546},{"text":"the","start":32.719},{"text":"ground,","start":32.892},{"text":"its","start":33.065},{"text":"steel","start":33.238},{"text":"would","start":33.411},{"text":"have","start":33.584},{"text":"to","start":33.756},{"text":"be","start":33.929},{"text":"50","start":34.102},{"text":"times","start":34.275},{"text":"stronger","start":34.448},{"text":"than","start":34.621},{"text":"steel","start":34.794},{"text":"is.","start":34.967}]},{"text":"So every bolt sheared. The building is sliding off its own floor.","show":37.8,"hide":42,"words":[{"text":"So","start":37.8},{"text":"every","start":38.045},{"text":"bolt","start":38.29},{"text":"sheared.","start":38.535},{"text":"The","start":38.78},{"text":"building","start":39.025},{"text":"is","start":39.27},{"text":"sliding","start":39.515},{"text":"off","start":39.76},{"text":"its","start":40.005},{"text":"own","start":40.25},{"text":"floor.","start":40.495}]}]},{"id":"town","n":6,"section":1,"title":false,"first":43.4,"end":55.75,"caps":[{"text":"It isn't only the station.","show":43.4,"hide":45.7,"words":[{"text":"It","start":43.4},{"text":"isn't","start":43.722},{"text":"only","start":44.044},{"text":"the","start":44.366},{"text":"station.","start":44.688}]},{"text":"Every building in town just left its foundations.","show":46.9,"hide":50.35,"words":[{"text":"Every","start":46.9},{"text":"building","start":47.202},{"text":"in","start":47.504},{"text":"town","start":47.806},{"text":"just","start":48.108},{"text":"left","start":48.409},{"text":"its","start":48.711},{"text":"foundations.","start":49.013}]},{"text":"So did every parked car, every lamp post and the top of every palm tree.","show":51.55,"hide":55.75,"words":[{"text":"So","start":51.55},{"text":"did","start":51.746},{"text":"every","start":51.942},{"text":"parked","start":52.138},{"text":"car,","start":52.334},{"text":"every","start":52.53},{"text":"lamp","start":52.726},{"text":"post","start":52.922},{"text":"and","start":53.118},{"text":"the","start":53.314},{"text":"top","start":53.51},{"text":"of","start":53.706},{"text":"every","start":53.902},{"text":"palm","start":54.098},{"text":"tree.","start":54.294}]}]},{"id":"people","n":7,"section":1,"title":false,"first":57.15,"end":78.75,"caps":[{"text":"Nobody on the platform has had time to react. They're doing 1,670 km/h, standing still.","show":57.15,"hide":61.35,"words":[{"text":"Nobody","start":57.15},{"text":"on","start":57.346},{"text":"the","start":57.542},{"text":"platform","start":57.738},{"text":"has","start":57.934},{"text":"had","start":58.13},{"text":"time","start":58.326},{"text":"to","start":58.522},{"text":"react.","start":58.718},{"text":"They're","start":58.914},{"text":"doing","start":59.11},{"text":"1,670","start":59.306},{"text":"km/h,","start":59.502},{"text":"standing","start":59.698},{"text":"still.","start":59.894}]},{"text":"The platform can only slow them by 25 km/h each second. And it ends in 20 metres.","show":62.75,"hide":66.95,"words":[{"text":"The","start":62.75},{"text":"platform","start":62.923},{"text":"can","start":63.096},{"text":"only","start":63.269},{"text":"slow","start":63.442},{"text":"them","start":63.615},{"text":"by","start":63.788},{"text":"25","start":63.961},{"text":"km/h","start":64.134},{"text":"each","start":64.306},{"text":"second.","start":64.479},{"text":"And","start":64.652},{"text":"it","start":64.825},{"text":"ends","start":64.998},{"text":"in","start":65.171},{"text":"20","start":65.344},{"text":"metres.","start":65.517}]},{"text":"They leave its end still standing up. They'll touch the ground 220 metres later.","show":68.55,"hide":72.75,"words":[{"text":"They","start":68.55},{"text":"leave","start":68.76},{"text":"its","start":68.97},{"text":"end","start":69.18},{"text":"still","start":69.39},{"text":"standing","start":69.6},{"text":"up.","start":69.81},{"text":"They'll","start":70.02},{"text":"touch","start":70.23},{"text":"the","start":70.44},{"text":"ground","start":70.65},{"text":"220","start":70.86},{"text":"metres","start":71.07},{"text":"later.","start":71.28}]},{"text":"The pigeons are fine. They were already in the air, and the air came too.","show":74.55,"hide":78.75,"words":[{"text":"The","start":74.55},{"text":"pigeons","start":74.746},{"text":"are","start":74.942},{"text":"fine.","start":75.138},{"text":"They","start":75.334},{"text":"were","start":75.53},{"text":"already","start":75.726},{"text":"in","start":75.922},{"text":"the","start":76.118},{"text":"air,","start":76.314},{"text":"and","start":76.51},{"text":"the","start":76.706},{"text":"air","start":76.902},{"text":"came","start":77.098},{"text":"too.","start":77.294}]}]},{"id":"train","n":8,"section":1,"title":false,"first":80.35,"end":96.15,"caps":[{"text":"Your train weighs 180 tonnes. Its wheels can't spin up this fast, so they skid.","show":80.35,"hide":84.55,"words":[{"text":"Your","start":80.35},{"text":"train","start":80.546},{"text":"weighs","start":80.742},{"text":"180","start":80.938},{"text":"tonnes.","start":81.134},{"text":"Its","start":81.33},{"text":"wheels","start":81.526},{"text":"can't","start":81.722},{"text":"spin","start":81.918},{"text":"up","start":82.114},{"text":"this","start":82.31},{"text":"fast,","start":82.506},{"text":"so","start":82.702},{"text":"they","start":82.898},{"text":"skid.","start":83.094}]},{"text":"Steel skidding on steel is a weak brake. Inside, it feels like the driver touched the brakes.","show":85.95,"hide":90.15,"words":[{"text":"Steel","start":85.95},{"text":"skidding","start":86.123},{"text":"on","start":86.296},{"text":"steel","start":86.469},{"text":"is","start":86.642},{"text":"a","start":86.815},{"text":"weak","start":86.988},{"text":"brake.","start":87.161},{"text":"Inside,","start":87.334},{"text":"it","start":87.506},{"text":"feels","start":87.679},{"text":"like","start":87.852},{"text":"the","start":88.025},{"text":"driver","start":88.198},{"text":"touched","start":88.371},{"text":"the","start":88.544},{"text":"brakes.","start":88.717}]},{"text":"The record for a train on wheels is 575 km/h. Yours is doing 1,670.","show":91.95,"hide":96.15,"words":[{"text":"The","start":91.95},{"text":"record","start":92.16},{"text":"for","start":92.37},{"text":"a","start":92.58},{"text":"train","start":92.79},{"text":"on","start":93},{"text":"wheels","start":93.21},{"text":"is","start":93.42},{"text":"575","start":93.63},{"text":"km/h.","start":93.84},{"text":"Yours","start":94.05},{"text":"is","start":94.26},{"text":"doing","start":94.47},{"text":"1,670.","start":94.68}]}]},{"id":"energy","n":9,"section":1,"title":false,"first":97.55,"end":107.15,"caps":[{"text":"At this speed, every kilogram carries the energy of 26 grams of TNT.","show":97.55,"hide":101.75,"words":[{"text":"At","start":97.55},{"text":"this","start":97.776},{"text":"speed,","start":98.002},{"text":"every","start":98.228},{"text":"kilogram","start":98.455},{"text":"carries","start":98.681},{"text":"the","start":98.907},{"text":"energy","start":99.133},{"text":"of","start":99.359},{"text":"26","start":99.585},{"text":"grams","start":99.812},{"text":"of","start":100.038},{"text":"TNT.","start":100.264}]},{"text":"Your train carries almost 5 tonnes of it. It's harmless, until something stops it.","show":102.95,"hide":107.15,"words":[{"text":"Your","start":102.95},{"text":"train","start":103.16},{"text":"carries","start":103.37},{"text":"almost","start":103.58},{"text":"5","start":103.79},{"text":"tonnes","start":104},{"text":"of","start":104.21},{"text":"it.","start":104.42},{"text":"It's","start":104.63},{"text":"harmless,","start":104.84},{"text":"until","start":105.05},{"text":"something","start":105.26},{"text":"stops","start":105.47},{"text":"it.","start":105.68}]}]},{"id":"hill","n":10,"section":1,"title":false,"first":108.55,"end":121.3,"caps":[{"text":"600 metres east of the station, the line runs into the hill.","show":108.55,"hide":112.55,"words":[{"text":"600","start":108.55},{"text":"metres","start":108.783},{"text":"east","start":109.017},{"text":"of","start":109.25},{"text":"the","start":109.483},{"text":"station,","start":109.717},{"text":"the","start":109.95},{"text":"line","start":110.183},{"text":"runs","start":110.417},{"text":"into","start":110.65},{"text":"the","start":110.883},{"text":"hill.","start":111.117}]},{"text":"The hill is part of the ground. It stopped.","show":113.75,"hide":116.9,"words":[{"text":"The","start":113.75},{"text":"hill","start":113.995},{"text":"is","start":114.24},{"text":"part","start":114.485},{"text":"of","start":114.73},{"text":"the","start":114.975},{"text":"ground.","start":115.22},{"text":"It","start":115.465},{"text":"stopped.","start":115.71}]},{"text":"The depot's shed just got there.","show":118.7,"hide":121.3,"words":[{"text":"The","start":118.7},{"text":"depot's","start":119.003},{"text":"shed","start":119.307},{"text":"just","start":119.61},{"text":"got","start":119.913},{"text":"there.","start":120.217}]}]},{"id":"depot","n":11,"section":1,"title":false,"first":122.7,"end":136.6,"caps":[{"text":"Six wagons of fuel were parked 210 metres from it. 80 tonnes each.","show":122.7,"hide":126.9,"words":[{"text":"Six","start":122.7},{"text":"wagons","start":122.926},{"text":"of","start":123.152},{"text":"fuel","start":123.378},{"text":"were","start":123.605},{"text":"parked","start":123.831},{"text":"210","start":124.057},{"text":"metres","start":124.283},{"text":"from","start":124.509},{"text":"it.","start":124.735},{"text":"80","start":124.962},{"text":"tonnes","start":125.188},{"text":"each.","start":125.414}]},{"text":"That's 2 tonnes of TNT per wagon, before the fuel.","show":127.9,"hide":131.4,"words":[{"text":"That's","start":127.9},{"text":"2","start":128.145},{"text":"tonnes","start":128.39},{"text":"of","start":128.635},{"text":"TNT","start":128.88},{"text":"per","start":129.125},{"text":"wagon,","start":129.37},{"text":"before","start":129.615},{"text":"the","start":129.86},{"text":"fuel.","start":130.105}]},{"text":"The first one just reached the rock.","show":133.8,"hide":136.6,"words":[{"text":"The","start":133.8},{"text":"first","start":134.08},{"text":"one","start":134.36},{"text":"just","start":134.64},{"text":"reached","start":134.92},{"text":"the","start":135.2},{"text":"rock.","start":135.48}]}]},{"id":"wind","n":12,"section":1,"title":false,"first":139.6,"end":154.55,"caps":[{"text":"The air didn't stop either. Against the hill it's a wind at 1.3 times the speed of sound.","show":139.6,"hide":143.8,"words":[{"text":"The","start":139.6},{"text":"air","start":139.763},{"text":"didn't","start":139.927},{"text":"stop","start":140.09},{"text":"either.","start":140.253},{"text":"Against","start":140.417},{"text":"the","start":140.58},{"text":"hill","start":140.743},{"text":"it's","start":140.907},{"text":"a","start":141.07},{"text":"wind","start":141.233},{"text":"at","start":141.397},{"text":"1.3","start":141.56},{"text":"times","start":141.723},{"text":"the","start":141.887},{"text":"speed","start":142.05},{"text":"of","start":142.213},{"text":"sound.","start":142.377}]},{"text":"Where the rock stops it, the air heats by 108 °C.","show":145.4,"hide":148.85,"words":[{"text":"Where","start":145.4},{"text":"the","start":145.62},{"text":"rock","start":145.839},{"text":"stops","start":146.059},{"text":"it,","start":146.278},{"text":"the","start":146.498},{"text":"air","start":146.717},{"text":"heats","start":146.937},{"text":"by","start":147.156},{"text":"108","start":147.376},{"text":"°C.","start":147.595}]},{"text":"It's pinning the fire to the hill and driving it over the top.","show":150.45,"hide":154.55,"words":[{"text":"It's","start":150.45},{"text":"pinning","start":150.671},{"text":"the","start":150.892},{"text":"fire","start":151.112},{"text":"to","start":151.333},{"text":"the","start":151.554},{"text":"hill","start":151.775},{"text":"and","start":151.995},{"text":"driving","start":152.216},{"text":"it","start":152.437},{"text":"over","start":152.658},{"text":"the","start":152.878},{"text":"top.","start":153.099}]}]},{"id":"sea","n":13,"section":1,"title":false,"first":156.55,"end":176.5,"caps":[{"text":"Behind the station is the harbour. The sea didn't stop either.","show":156.55,"hide":160.65,"words":[{"text":"Behind","start":156.55},{"text":"the","start":156.811},{"text":"station","start":157.072},{"text":"is","start":157.333},{"text":"the","start":157.594},{"text":"harbour.","start":157.855},{"text":"The","start":158.115},{"text":"sea","start":158.376},{"text":"didn't","start":158.637},{"text":"stop","start":158.898},{"text":"either.","start":159.159}]},{"text":"This is what got in front of the Sun.","show":162.25,"hide":165.1,"words":[{"text":"This","start":162.25},{"text":"is","start":162.472},{"text":"what","start":162.693},{"text":"got","start":162.915},{"text":"in","start":163.137},{"text":"front","start":163.358},{"text":"of","start":163.58},{"text":"the","start":163.802},{"text":"Sun.","start":164.023}]},{"text":"Every metre of this quay is being hit by 4,800 tonnes of water.","show":166.7,"hide":170.85,"words":[{"text":"Every","start":166.7},{"text":"metre","start":166.923},{"text":"of","start":167.147},{"text":"this","start":167.37},{"text":"quay","start":167.594},{"text":"is","start":167.817},{"text":"being","start":168.041},{"text":"hit","start":168.264},{"text":"by","start":168.488},{"text":"4,800","start":168.711},{"text":"tonnes","start":168.935},{"text":"of","start":169.158},{"text":"water.","start":169.382}]},{"text":"The ferry was 290 metres out. It weighs 2,000 tonnes.","show":172.85,"hide":176.5,"words":[{"text":"The","start":172.85},{"text":"ferry","start":173.106},{"text":"was","start":173.361},{"text":"290","start":173.617},{"text":"metres","start":173.872},{"text":"out.","start":174.128},{"text":"It","start":174.383},{"text":"weighs","start":174.639},{"text":"2,000","start":174.894},{"text":"tonnes.","start":175.15}]}]},{"id":"up","n":14,"section":1,"title":false,"first":178.1,"end":187.75,"caps":[{"text":"The water can only go up. It's climbing at over 1,000 km/h.","show":178.1,"hide":182.05,"words":[{"text":"The","start":178.1},{"text":"water","start":178.33},{"text":"can","start":178.561},{"text":"only","start":178.791},{"text":"go","start":179.022},{"text":"up.","start":179.252},{"text":"It's","start":179.483},{"text":"climbing","start":179.713},{"text":"at","start":179.943},{"text":"over","start":180.174},{"text":"1,000","start":180.404},{"text":"km/h.","start":180.635}]},{"text":"This is happening on every west-facing shore on Earth.","show":184.05,"hide":187.75,"words":[{"text":"This","start":184.05},{"text":"is","start":184.338},{"text":"happening","start":184.626},{"text":"on","start":184.913},{"text":"every","start":185.201},{"text":"west-facing","start":185.489},{"text":"shore","start":185.777},{"text":"on","start":186.064},{"text":"Earth.","start":186.352}]}]},{"id":"fall","n":15,"section":1,"title":false,"first":189.15,"end":202.75,"caps":[{"text":"One second is only long enough to fall 4.9 metres.","show":189.15,"hide":192.65,"words":[{"text":"One","start":189.15},{"text":"second","start":189.395},{"text":"is","start":189.64},{"text":"only","start":189.885},{"text":"long","start":190.13},{"text":"enough","start":190.375},{"text":"to","start":190.62},{"text":"fall","start":190.865},{"text":"4.9","start":191.11},{"text":"metres.","start":191.355}]},{"text":"The station's roof was 5.6 metres up. It's still in the air.","show":194.05,"hide":198.05,"words":[{"text":"The","start":194.05},{"text":"station's","start":194.283},{"text":"roof","start":194.517},{"text":"was","start":194.75},{"text":"5.6","start":194.983},{"text":"metres","start":195.217},{"text":"up.","start":195.45},{"text":"It's","start":195.683},{"text":"still","start":195.917},{"text":"in","start":196.15},{"text":"the","start":196.383},{"text":"air.","start":196.617}]},{"text":"So is the woman who was on the footbridge.","show":199.65,"hide":202.75,"words":[{"text":"So","start":199.65},{"text":"is","start":199.891},{"text":"the","start":200.132},{"text":"woman","start":200.373},{"text":"who","start":200.614},{"text":"was","start":200.856},{"text":"on","start":201.097},{"text":"the","start":201.338},{"text":"footbridge.","start":201.579}]}]},{"id":"sky","n":16,"section":1,"title":false,"first":204.15,"end":212.95,"caps":[{"text":"Planes fly in the air, and the air never stopped.","show":204.15,"hide":207.6,"words":[{"text":"Planes","start":204.15},{"text":"fly","start":204.392},{"text":"in","start":204.633},{"text":"the","start":204.875},{"text":"air,","start":205.116},{"text":"and","start":205.358},{"text":"the","start":205.599},{"text":"air","start":205.841},{"text":"never","start":206.082},{"text":"stopped.","start":206.324}]},{"text":"Right now, the safest place on Earth is 10 kilometres above it.","show":208.8,"hide":212.95,"words":[{"text":"Right","start":208.8},{"text":"now,","start":209.042},{"text":"the","start":209.284},{"text":"safest","start":209.526},{"text":"place","start":209.768},{"text":"on","start":210.01},{"text":"Earth","start":210.253},{"text":"is","start":210.495},{"text":"10","start":210.737},{"text":"kilometres","start":210.979},{"text":"above","start":211.221},{"text":"it.","start":211.463}]}]},{"id":"count","n":17,"section":1,"title":false,"first":214.15,"end":228.5,"caps":[{"text":"Your train has slid 410 metres. The hill is dead ahead.","show":214.15,"hide":217.9,"words":[{"text":"Your","start":214.15},{"text":"train","start":214.389},{"text":"has","start":214.627},{"text":"slid","start":214.866},{"text":"410","start":215.105},{"text":"metres.","start":215.343},{"text":"The","start":215.582},{"text":"hill","start":215.82},{"text":"is","start":216.059},{"text":"dead","start":216.298},{"text":"ahead.","start":216.536}]},{"text":"Nobody on board has heard a thing. The hill is coming faster than its own sound.","show":219.1,"hide":223.3,"words":[{"text":"Nobody","start":219.1},{"text":"on","start":219.284},{"text":"board","start":219.468},{"text":"has","start":219.651},{"text":"heard","start":219.835},{"text":"a","start":220.019},{"text":"thing.","start":220.203},{"text":"The","start":220.386},{"text":"hill","start":220.57},{"text":"is","start":220.754},{"text":"coming","start":220.938},{"text":"faster","start":221.121},{"text":"than","start":221.305},{"text":"its","start":221.489},{"text":"own","start":221.672},{"text":"sound.","start":221.856}]},{"text":"The ground starts turning again in 0.05 seconds.","show":225.1,"hide":228.5,"words":[{"text":"The","start":225.1},{"text":"ground","start":225.398},{"text":"starts","start":225.695},{"text":"turning","start":225.993},{"text":"again","start":226.29},{"text":"in","start":226.588},{"text":"0.05","start":226.885},{"text":"seconds.","start":227.183}]}]},{"id":"back","n":18,"section":2,"title":false,"first":230.1,"end":243.15,"caps":[{"text":"5:42:01 PM. The ground is turning again.","show":230.1,"hide":233.1,"words":[{"text":"5:42:01","start":230.1},{"text":"PM.","start":230.4},{"text":"The","start":230.7},{"text":"ground","start":231},{"text":"is","start":231.3},{"text":"turning","start":231.6},{"text":"again.","start":231.9}]},{"text":"Everything still in motion is suddenly standing still.","show":234.9,"hide":238.6,"words":[{"text":"Everything","start":234.9},{"text":"still","start":235.224},{"text":"in","start":235.548},{"text":"motion","start":235.871},{"text":"is","start":236.195},{"text":"suddenly","start":236.519},{"text":"standing","start":236.843},{"text":"still.","start":237.166}]},{"text":"Your train is 150 metres short of the hill.","show":240,"hide":243.15,"words":[{"text":"Your","start":240},{"text":"train","start":240.245},{"text":"is","start":240.49},{"text":"150","start":240.735},{"text":"metres","start":240.98},{"text":"short","start":241.225},{"text":"of","start":241.47},{"text":"the","start":241.715},{"text":"hill.","start":241.96}]}]},{"id":"twist","n":19,"section":3,"title":false,"first":245.55,"end":259.4,"caps":[{"text":"But the ground stopped the fire, the air and the sea. They have no speed left.","show":245.55,"hide":249.75,"words":[{"text":"But","start":245.55},{"text":"the","start":245.734},{"text":"ground","start":245.918},{"text":"stopped","start":246.101},{"text":"the","start":246.285},{"text":"fire,","start":246.469},{"text":"the","start":246.653},{"text":"air","start":246.836},{"text":"and","start":247.02},{"text":"the","start":247.204},{"text":"sea.","start":247.388},{"text":"They","start":247.571},{"text":"have","start":247.755},{"text":"no","start":247.939},{"text":"speed","start":248.123},{"text":"left.","start":248.306}]},{"text":"And the ground is doing 1,670 km/h again. From your seat, all of it was just thrown west.","show":250.95,"hide":255.15,"words":[{"text":"And","start":250.95},{"text":"the","start":251.113},{"text":"ground","start":251.277},{"text":"is","start":251.44},{"text":"doing","start":251.603},{"text":"1,670","start":251.767},{"text":"km/h","start":251.93},{"text":"again.","start":252.093},{"text":"From","start":252.257},{"text":"your","start":252.42},{"text":"seat,","start":252.583},{"text":"all","start":252.747},{"text":"of","start":252.91},{"text":"it","start":253.073},{"text":"was","start":253.237},{"text":"just","start":253.4},{"text":"thrown","start":253.563},{"text":"west.","start":253.727}]},{"text":"It reaches your train in 0.2 seconds.","show":256.55,"hide":259.4,"words":[{"text":"It","start":256.55},{"text":"reaches","start":256.835},{"text":"your","start":257.12},{"text":"train","start":257.405},{"text":"in","start":257.69},{"text":"0.2","start":257.975},{"text":"seconds.","start":258.26}]}]},{"id":"question","n":20,"section":3,"title":false,"first":260.6,"end":263.85,"caps":[{"text":"Where on Earth would you want to be standing?","show":260.6,"hide":263.85,"words":[{"text":"Where","start":260.6},{"text":"on","start":260.853},{"text":"Earth","start":261.106},{"text":"would","start":261.358},{"text":"you","start":261.611},{"text":"want","start":261.864},{"text":"to","start":262.117},{"text":"be","start":262.369},{"text":"standing?","start":262.622}]}]}]};
